{"hypotheses": [
  {
    "name": "R&D-Intangibles Asymmetric Premium",
    "mechanism": "Firms with high R&D investment relative to market cap but low realized patent citation intensity (CitationsRD) may be undervalued due to market uncertainty about future intangible payoff, while simultaneously being penalized in traditional intangibles factor screens. By offsetting IntanBM with CitationsRD, this composite captures mispricing due to delayed recognition of R&D payoffs, especially in environments with ambiguous tangible value.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": -1.0, "primitive": "CitationsRD"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "RD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.58,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Delayed Equity Duration-Cash Premium",
    "mechanism": "This composite targets firms with high equity duration (EquityDuration) that simultaneously have high cash reserves (Cash) but low payout yields (NetPayoutYield), exploiting the misalignment between market discounting for long-dated payoffs and the near-term flexibility provided by liquidity buffers. The return enhancement comes from the market underweighting near-term option value in long-duration names.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EquityDuration"},
        {"weight": 1.0, "primitive": "Cash"},
        {"weight": -1.0, "primitive": "NetPayoutYield"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.54,
    "expected_decay_half_life_months": 40
  },
  {
    "name": "Customer-Supplier Resilience Blend",
    "mechanism": "By combining customer momentum (iomom_cust) and supplier momentum (iomom_supp), but offsetting with industry asset concentration (HerfAsset), this composite captures cross-supply-chain momentum that is more persistent in less concentrated industries, where competitive dynamics allow information to diffuse without being arbitraged away rapidly.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 1.0, "primitive": "iomom_supp"},
        {"weight": -0.5, "primitive": "HerfAsset"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "iomom_cust", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.49,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Analyst-Mediated Downside Disagreement",
    "mechanism": "Firms with high forecast dispersion (ForecastDispersion) but recent downward analyst revisions (AnalystRevision) and weak earnings consistency (EarningsConsistency) are penalized excessively when negative news emerges, leading to overreaction. The composite systematically exploits this by blending the disagreement premium with negative revision momentum and earnings surprise asymmetry.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": -1.0, "primitive": "AnalystRevision"},
        {"weight": -0.5, "primitive": "EarningsConsistency"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "correlation", "primitive": "ForecastDispersion", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.62,
    "expected_decay_half_life_months": 8
  },
  {
    "name": "Event-Driven Asset Churn Anomaly",
    "mechanism": "By combining change in equity (ChEQ), change in long-term investment (DelLTI), and abnormal accruals (AbnormalAccruals), the composite captures firms undergoing asset base restructuring often missed by static value or growth screens. Such asset churn around corporate events is underpriced, especially when not accompanied by earnings manipulation (negative AbnormalAccruals weight).",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ChEQ"},
        {"weight": 1.0, "primitive": "DelLTI"},
        {"weight": -0.5, "primitive": "AbnormalAccruals"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.56,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Off-Season Return Dispersion Arbitrage",
    "mechanism": "This composite exploits the combination of off-season momentum (MomOffSeason) and the volatility smirk (skew1), hedged by realized volatility (RealizedVol). It aims to capture the spread in post-earnings-announcement drift and volatility surface asymmetries, generating a return premium when option-implied risk is misaligned with drift seasonality.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "MomOffSeason"},
        {"weight": 0.5, "primitive": "skew1"},
        {"weight": -1.0, "primitive": "RealizedVol"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "MomOffSeason", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.47,
    "expected_decay_half_life_months": 14
  },
  {
    "name": "Governance-Illiquidity Contrarian Blend",
    "mechanism": "The blend of governance (Governance), Amihud illiquidity (Illiquidity), and deferred revenue changes (DelDRC) targets stocks with strong governance but low market liquidity and recent revenue deferral, exploiting market underreaction to latent fundamental improvements in illiquid, well-governed names that defer current revenue for recognized future income.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Governance"},
        {"weight": 0.5, "primitive": "Illiquidity"},
        {"weight": 1.0, "primitive": "DelDRC"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.46,
    "expected_decay_half_life_months": 32
  },
  {
    "name": "Forecast Error Variance Reversal",
    "mechanism": "This composite exploits stock return reversals that are pronounced in firms with high predicted analyst forecast error (PredictedFE) and high variance of cash-flow to price (VarCF), but low share turnover volatility (std_turn). The effect arises from periodic mean-reversion in pricing error and transitory cash flow volatility, not fully arbitraged due to investor attention limits.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "PredictedFE"},
        {"weight": 1.0, "primitive": "VarCF"},
        {"weight": -1.0, "primitive": "std_turn"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "PredictedFE", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.51,
    "expected_decay_half_life_months": 15
  }
]}
